llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Fenofibrate, despite being practically insoluble in aqueous media, has approximately 30% oral bioavailability in humans, supporting that a lipophilic, poorly soluble molecule can still exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib has an absolute oral bioavailability of 31.8% in humans after a 150 mg oral dose, providing direct human evidence that a lipophilic heteroaromatic amide can achieve F above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Glafenine has a mean absolute bioavailability of approximately 0.33 in healthy volunteers, another lipophilic heteroaromatic drug exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Sorafenib, a poorly soluble lipophilic oral drug, has reported oral bioavailability of approximately 38-49% in humans, supporting high F for the query despite solubility limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tenoxicam has essentially complete oral bioavailability (~100%) in humans, demonstrating that lipophilic, poorly soluble drugs can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Belumosudil has an absolute oral bioavailability of 64% after a single 200 mg oral dose in healthy subjects, providing additional human evidence for high F in a heteroaromatic amide-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One sorafenib analysis reports an oral bioavailability of approximately 8.5%, which would be below the 20% threshold; however, this conflicts with multiple other sorafenib records reporting 38-49% and is outweighed by the consistent high-F evidence from other analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, poorly soluble neutral heteroaromatic amide/thioether. Direct human absolute bioavailability values for structurally analogous drugs (fenofibrate ~30%, vismodegib 31.8%, glafenine ~33%, sorafenib 38-49%, tenoxicam ~100%, belumosudil 64%) consistently exceed the 20% threshold. The one low sorafenib estimate (~8.5%) is an outlier and does not overturn the weight of evidence. Therefore predict high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "Morgan similarities between the query and evidence molecules are low (0.18-0.26), limiting structural transferability.",
    "Conflicting sorafenib bioavailability reports create uncertainty about the exact F value for that analogue.",
    "High lipophilicity and low fraction sp3 may cause formulation-dependent or saturable absorption in humans."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

